```cpp
#include <string>
#include <sstream>

std::string convertToHtml(const std::string& inputStr) {
    std::string htmlStr;
    std::stringstream ss;

    // Iterate over each character in the input string
    for (const auto c : inputStr) {
        switch (c) {
            case '_':
                ss << "<sub>"; // Subscript
                break;
            case '^':
                ss << "<sup>"; // Superscript
                break;
            case '{':
                ss << "<span style='font-size: "; // Custom font size
                break;
            case '}':
                ss << "px'>"; // Close the span element
                break;
            case '[':
                ss << "<span style='color: "; // Custom font color
                break;
            case ']':
                ss << "'>"; // Close the span element
                break;
            default:
                ss << c; // Leave other characters as is
                break;
        }
    }

    // Close any open HTML tags
    while (!ss.eof()) {
        switch (ss.peek()) {
            case '_':
                ss << "</sub>";
                break;
            case '^':
                ss << "</sup>";
                break;
            case '{':
                ss << "</span>";
                break;
            case '[':
                ss << "</span>";
                break;
            default:
                break;
        }
        ss.ignore(1); // Consume the character
