```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    // Установить слово для поиска
    string searchWord = "example";

    // Путь к файлу
    string filePath = "input.txt";

    // Считать количество вхождений слова в файл
    int wordCount = 0;
    ifstream file(filePath);
    if (file.is_open()) {
        string line;
        while (getline(file, line)) {
            // Преобразовать строку в нижний регистр дляcase-insensitive поиска
            transform(line.begin(), line.end(), line.begin(), ::tolower);
            size_t pos = std::search(line.begin(), line.end(), searchWord.begin(), searchWord.end(), ::nequal);
            while (pos != string::npos) {
                wordCount++;
                pos = std::search(pos + 1, line.end(), searchWord.begin(), searchWord.end(), ::nequal);
            }
        }
        file.close();
    } else {
        cout << "Unable to open file: " << filePath << endl;
        return 1;
    }

    // Вывести результат
    cout << "Word '" << searchWord << "' appears " << wordCount << " times in " << filePath << endl;

    return 0;
}
```

В коде, сначала необходимо указать слово для поиска и путь к файлу. В цикле, каждая строка файла преобразуется в нижний регистр для case-insensitive поиска, а затем, с помощью функции `search`, ищется первое вхождение слова в строке. Если найдено, то увеличивается счетчик `wordCount`, и цикл продолжает поиск остальных вхождений в строке. После завершения чтения файла, выводится количество вхождений слова в файл. 

